{"command": "node -e "
import('./server.mjs').then(async ({callTool, listTools}) => {
  // Test list
  console.log('Tools:', JSON.stringify(await listTools()));

  // Test: duplicates rejected
  try { await callTool('users_get_many', {user_ids:['u1','u1']}); console.log('FAIL: dup allowed'); }
  catch(e){ console.log('dup rejected:', e.message); }

  // Test: empty array rejected
  try { await callTool('users_get_many', {user_ids:[]}); console.log('FAIL: empty allowed'); }
  catch(e){ console.log('empty rejected:', e.message); }

  // Test: too many rejected
  try { await callTool('users_get_many', {user_ids:['a','b','c','d','e','f']}); console.log('FAIL: too many allowed'); }
  catch(e){ console.log('too many rejected:', e.message); }

  // Test: extra field rejected
  try { await callTool('users_get_many', {user_ids:['u1'], extra:1}); console.log('FAIL: extra field allowed'); }
  catch(e){ console.log('extra field rejected:', e.message); }

  // Test: unknown tool rejected
  try { await callTool('unknown_tool', {}); console.log('FAIL: unknown tool allowed'); }
  catch(e){ console.log('unknown tool rejected:', e.message); }

  // Test: non-array rejected
  try { await callTool('users_get_many', {user_ids:'u1'}); console.log('FAIL: non-array allowed'); }
  catch(e){ console.log('non-array rejected:', e.message); }

  // Test: non-string element rejected
  try { await callTool('users_get_many', {user_ids:[1]}); console.log('FAIL: non-string element allowed'); }
  catch(e){ console.log('non-string element rejected:', e.message); }

  // Test: normal batch with missing in order
  const r = await callTool('users_get_many', {user_ids:['u3','missing','u1']});
  console.log('result text:', JSON.stringify(r.content[0].text));
});
""}

